import { useErrorBoundary } from '@suspensive/react';
import clsx from 'clsx';
import { FormProvider, useForm } from 'react-hook-form';
import { useTxSearchMutation } from '~/entities/exchange/api/hooks/use-tx-search-mutation';
import { useExchangeNavigation } from '~/entities/exchange/lib/use-exchange-navigation';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';
import QRKitImg from '~/shared/assets/img/qr_kit_sample.png';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { TextInput } from '~/shared/ui/text-input/text-input';

type Inputs = {
  txCd: string;
};

export const InputTransactionNumber = () => {
  const { navigateBack } = useNavigate();
  const { navigateToExchange } = useExchangeNavigation();
  const form = useForm<Inputs>({ mode: 'all' });
  const { register, handleSubmit, watch } = form;
  const txCd = watch('txCd');
  const { mutateAsync: txSearch } = useTxSearchMutation({ throwOnError: false });
  const closePage = () => {
    navigateBack();
  };
  const { setError } = useErrorBoundary();

  const onSubmit = async (data: Inputs) => {
    const result = await txSearch({ tbPayMastr: { txCd: data.txCd } });

    if (!result) {
      setError(new Error(i18n.t('validation:invalidTransactionNumber')));
      return;
    }
    navigateBack();

    try {
      await navigateToExchange({
        tbPayMastr: result,
        txCd: data.txCd,
        isAppToApp: false,
        isQrScan: true,
        trnscTypeCd: TrnscTypeCd.결제,
      });
    } catch {
      setError(new Error(i18n.t('validation:invalidTransactionNumber')));
    }
  };

  return (
    <FormProvider {...form}>
      <div className="wrap has-btm-btn">
        <div className="pay-num-ipt sub full-height">
          <div className="pay-num-top">
            <button type="button" onClick={closePage} className="btn close-btn">
              <span>{i18n.t('close')}</span>
            </button>
          </div>
          <div className="pay-num-tit">
            <h2 className="whitespace-pre-line break-words">{i18n.t('validation:enterTransactionNumberDirectly')}</h2>
          </div>
          <div className="kit-sample-img">
            <img src={QRKitImg} />
          </div>
          <form onSubmit={handleSubmit(onSubmit)} className="ipt-form-area no-flex pt0">
            <TextInput
              label={i18n.t('validation:enterCode')}
              {...register('txCd', {
                required: true,
              })}
            />
          </form>
        </div>
        <div className="btm-btn-area">
          <button
            type="button"
            className={clsx('btm-btn app', { disabled: !txCd })}
            id="charge"
            onClick={handleSubmit(onSubmit)}
          >
            {i18n.t('confirm')}
          </button>
        </div>
      </div>
    </FormProvider>
  );
};
